const express = require('express');
const fs = require('node:fs');
const path = require('node:path');
const { requireCacheUser } = require('../auth/cacheAuth');

const app = express();

app.put('/v2/artifacts/:hash', requireCacheUser, (req, res) => {
  const { hash } = req.params;
  const teamId = req.query.teamId || req.headers['x-artifact-client-id'];

  if (!teamId) {
    return res.status(400).json({ error: 'Team identifier required' });
  }

  // Ensure authenticated user has write permissions for the specified team cache
  if (!req.user.writableTeams?.includes(teamId)) {
    return res.status(403).json({ error: 'Access denied: No write permission for target team cache' });
  }

  const targetPath = path.join('/var/cache/turbo', teamId, `${hash}.tar.gz`);
  fs.mkdirSync(path.dirname(targetPath), { recursive: true });

  const writeStream = fs.createWriteStream(targetPath);
  req.pipe(writeStream);

  writeStream.on('finish', () => {
    res.status(200).json({ status: 'cached', hash, teamId });
  });
});

module.exports = app;
